protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Validate parameters
    if (type == null) {
        throw new IllegalArgumentException("type cannot be null");
    }
    if (value == null) {
        throw new IllegalArgumentException("value cannot be null");
    }

    // Check if the type is a Character class
    if (type == Character.class) {
        return Character.valueOf((char) value);
    }

    // If the type is not a Character class, attempt to convert the value to a string
    String strValue = String.valueOf(value);

    // Check if the string value contains only one character
    if (strValue.length() == 1) {
        return Character.valueOf(strValue.charAt(0));
    }

    // If the string value does not contain only one character, throw an exception
    throw new IllegalArgumentException("Cannot convert '" + strValue + "' to Character");
}

