public static int digitValue(char c) {
    int digit = Character.digit(c);
    if (digit != -1) {
        return digit;
    } else {
        if (c >= '0' && c <= '9') {
            return c - '0';
        } else if (c >= 'a' && c <= 'z') {
            return c - 'a' + 10;
        } else if (c >= 'A' && c <= 'Z') {
            return c - 'A' + 10;
        } else {
            throw new IllegalArgumentException("Invalid digit character: " + c);
        }
    }
}

