public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuffer sb = new StringBuffer();
    boolean backslash = false;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (backslash) {
            if (c == '\\') {
                sb.append('\\');
            } else if (c == 'n') {
                sb.append('\n');
            } else if (c == 'r') {
                sb.append('\r');
            } else if (c == 't') {
                sb.append('\t');
            } else if (c == 'f') {
                sb.append('\f');
            } else if (c == '"') {
                sb.append('"');
            } else if (c == '\'') {
                sb.append('\'');
            } else {
                // Character literal
                sb.append('\\');
                sb.append(c);
            }
            backslash = false;
        } else if (c == '\\') {
            backslash = true;
        } else {
            sb.append(c);
        }
    }
    if (backslash) {
        throw new Exception("Invalid escape sequence");
    }
    return sb.toString();
}

