private List<Integer> computeUpperBounds(List<K> keys) {
    // initialize the upper bounds list with the keys
    List<Integer> upperBounds = new ArrayList<>(keys);
    // loop through the keys and check for duplicates
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        // check if the current key is already in the upper bounds list
        if (upperBounds.contains(key)) {
            // find the first instance of the key in the upper bounds list
            int index = upperBounds.indexOf(key);
            // iterate through the upper bounds list starting from the first instance of the key
            for (int j = index; j < upperBounds.size(); j++) {
                // if the current key is found again, it means there are duplicates, so set the upper bound to the minimum of the current key and the previous key
                if (upperBounds.get(j).equals(key)) {
                    upperBounds.set(j, Math.min(key, upperBounds.get(j - 1)));
                }
            }
        }
    }
    return upperBounds;
}

